#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
#include <tuple>
#include <algorithm>
using namespace std;

using ll = long long;
const ll INF = 1000000009;

struct Edge {
    int u, v, flow, capacity;
    Edge(int u, int v, int flow, int capacity) : u(u), v(v), flow(flow), capacity(capacity) {}
};

int source, sink;
vector<vector<int>> graph;
vector<Edge> edges;

void addEdge(int u, int v, int capacity) {
    graph[u].push_back(edges.size());
    edges.emplace_back(u, v, 0, capacity);
    graph[v].push_back(edges.size());
    edges.emplace_back(v, u, 0, 0);
}

int ptr[1001], dist[1001];

bool bfs() {
    memset(dist, -1, sizeof(dist));
    dist[source] = 0;
    queue<int> q;
    q.push(source);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int idx : graph[u]) {
            const auto& e = edges[idx];
            if (dist[e.v] == -1 && e.flow < e.capacity) {
                dist[e.v] = dist[u] + 1;
                q.push(e.v);
                if (e.v == sink) return true;
            }
        }
    }
    return false;
}

ll dfs(int u, ll flow) {
    if (u == sink || flow == 0) return flow;
    for (int& i = ptr[u]; i < (int)graph[u].size(); ++i) {
        int idx = graph[u][i];
        auto& e = edges[idx];
        if (dist[e.v] != dist[u] + 1) continue;
        ll pushed = dfs(e.v, min(flow, (ll)e.capacity - e.flow));
        if (pushed) {
            e.flow += pushed;
            edges[idx ^ 1].flow -= pushed;
            return pushed;
        }
    }
    return 0;
}

ll dinic() {
    ll totalFlow = 0;
    while (bfs()) {
        memset(ptr, 0, sizeof(ptr));
        ll pushed;
        while ((pushed = dfs(source, INF)) > 0)
            totalFlow += pushed;
    }
    return totalFlow;
}

string scientists[101], reactors[101];
bool reach[10][10][10][10];
int vis[101][101];
int unusable[10][10];
int N, M;

bool inBounds(int r, int c) {
    return r >= 0 && c >= 0 && r < N && c < M;
}

int nodeID(int x, int y) {
    return 1 + M * x + y;
}

int main() {
    ios::sync_with_stdio(false);
    int T;
    cin >> N >> T;
    ++T;
    M = N;
    sink = M * M * 2 + 1;
    source = 0;
    graph.resize(M * M * 2 + 2);
    queue<pair<int, int>> q;
    for (int i = 0; i < N; ++i) cin >> scientists[i];
    for (int i = 0; i < N; ++i) {
        cin >> reactors[i];
        for (int j = 0; j < M; ++j) {
            unusable[i][j] = INF;
            if (reactors[i][j] == 'Z') {
                q.push({i, j});
                unusable[i][j] = 1;
            }
        }
    }
    while (!q.empty()) {
        auto [x, y] = q.front(); q.pop();
        for (int di = -1; di <= 1; ++di)
            for (int dj = -1; dj <= 1; ++dj)
                if (abs(di) + abs(dj) == 1) {
                    int nx = x + di, ny = y + dj;
                    if (inBounds(nx, ny) && unusable[nx][ny] == INF && scientists[nx][ny] != 'Y') {
                        unusable[nx][ny] = unusable[x][y] + 1;
                        q.push({nx, ny});
                    }
                }
    }
    for (int x = 0; x < N; ++x)
        for (int y = 0; y < M; ++y) {
            if (scientists[x][y] >= '1' && scientists[x][y] <= '9')
                addEdge(source, nodeID(x, y), scientists[x][y] - '0');
            if (reactors[x][y] >= '1' && reactors[x][y] <= '9')
                addEdge(N * N + nodeID(x, y), sink, reactors[x][y] - '0');
            for (int X = 0; X < N; ++X)
                for (int Y = 0; Y < M; ++Y) {
                    if (scientists[x][y] == 'Y' || scientists[x][y] == 'Z' ||
                        reactors[X][Y] == 'Y' || reactors[X][Y] == 'Z')
                        continue;
                    memset(vis, 0, sizeof(vis));
                    queue<tuple<int, int, int>> bq;
                    bq.emplace(x, y, 1);
                    vis[x][y] = 1;
                    while (!bq.empty()) {
                        auto [cx, cy, t] = bq.front(); bq.pop();
                        if (cx == X && cy == Y) {
                            vis[cx][cy] = 1;
                            break;
                        }
                        if (t >= unusable[cx][cy] || t >= T) continue;
                        for (int di = -1; di <= 1; ++di)
                            for (int dj = -1; dj <= 1; ++dj)
                                if (abs(di) + abs(dj) == 1) {
                                    int nx = cx + di, ny = cy + dj;
                                    if (inBounds(nx, ny) && !vis[nx][ny] &&
                                        scientists[nx][ny] != 'Y' && scientists[nx][ny] != 'Z' &&
                                        t + 1 <= unusable[nx][ny]) {
                                        vis[nx][ny] = 1;
                                        bq.emplace(nx, ny, t + 1);
                                    }
                                }
                    }
                    if (vis[X][Y])
                        addEdge(nodeID(x, y), N * N + nodeID(X, Y), INF);
                }
        }
    cout << dinic() << '\n';
}
